### 📖 Explanation:
```
PROBLEM:  You need to create objects, but you don't want your code
          to know the EXACT class being created.
          You want to delegate the creation decision to subclasses
          or based on runtime data.

SOLUTION: Define an interface for creating objects.
          Let subclasses / factory functions decide which class to instantiate.

ANALOGY:  RESTAURANT MENU
  You say: "I want a pizza"
  Waiter (Factory) decides: which chef makes it, which oven, which recipe.
  You get: a Pizza — without knowing HOW it was made.

  If the restaurant gets a new wood-fire oven:
  → Waiter's creation process changes
  → YOUR ORDER stays the same: "Give me a pizza"
  → You're insulated from creation details
```

```python name=factory_pattern.py
# ══════════════════════════════════════════════════
#  PATTERN 2: FACTORY METHOD
#  Create objects without knowing the exact class
# ══════════════════════════════════════════════════
from abc import ABC, abstractmethod

# ─── The products (what gets created) ───
class Notification(ABC):
    @abstractmethod
    def send(self, recipient: str, message: str) -> bool: pass

    @abstractmethod
    def get_type(self) -> str: pass

    def deliver(self, recipient: str, message: str) -> dict:
        """Template — calls send() then returns result"""
        print(f"  📤 Delivering {self.get_type()} to {recipient}")
        success = self.send(recipient, message)
        return {
            "type"      : self.get_type(),
            "recipient" : recipient,
            "success"   : success,
        }

class EmailNotification(Notification):
    def __init__(self, smtp_host="smtp.gmail.com"):
        self.smtp_host = smtp_host

    def send(self, recipient, message):
        print(f"  📧 EMAIL → {recipient} via {self.smtp_host}")
        print(f"     Message: {message[:50]}...")
        return True

    def get_type(self): return "EMAIL"

class SMSNotification(Notification):
    def __init__(self, provider="Twilio"):
        self.provider = provider

    def send(self, recipient, message):
        print(f"  📱 SMS → {recipient} via {self.provider}")
        print(f"     Message: {message[:160]}")  # SMS limit!
        return True

    def get_type(self): return "SMS"

class PushNotification(Notification):
    def __init__(self, platform="FCM"):
        self.platform = platform

    def send(self, recipient, message):
        print(f"  🔔 PUSH → {recipient} via {self.platform}")
        print(f"     Alert: {message[:100]}")
        return True

    def get_type(self): return "PUSH"

class WhatsAppNotification(Notification):
    def send(self, recipient, message):
        print(f"  💬 WhatsApp → {recipient}")
        print(f"     Message: {message[:1000]}")
        return True

    def get_type(self): return "WHATSAPP"

# ─── Factory Method 1: Simple Factory Function ───
def create_notification(channel: str,
                        **kwargs) -> Notification:
    """
    Simple Factory Function.
    Caller says WHAT they want, factory decides HOW to create it.
    """
    factories = {
        "email"    : lambda: EmailNotification(kwargs.get("smtp_host", "smtp.gmail.com")),
        "sms"      : lambda: SMSNotification(kwargs.get("provider", "Twilio")),
        "push"     : lambda: PushNotification(kwargs.get("platform", "FCM")),
        "whatsapp" : lambda: WhatsAppNotification(),
    }
    if channel not in factories:
        raise ValueError(f"Unknown channel: {channel}. "
                         f"Options: {list(factories.keys())}")
    return factories[channel]()

# ─── Factory Method 2: Abstract Factory (for families of objects) ───
class NotificationFactory(ABC):
    """
    Abstract Factory — creates FAMILIES of related objects.
    Different factories for different environments/regions.
    """
    @abstractmethod
    def create_transactional(self) -> Notification: pass

    @abstractmethod
    def create_marketing(self) -> Notification: pass

    @abstractmethod
    def create_otp(self) -> Notification: pass

    def notify_user(self, user_id: str, txn_msg: str,
                    mkt_msg: str, otp: str):
        """Uses all three notification types"""
        txn = self.create_transactional()
        mkt = self.create_marketing()
        otp_n = self.create_otp()

        txn.deliver(user_id, txn_msg)
        mkt.deliver(user_id, mkt_msg)
        otp_n.deliver(user_id, f"Your OTP: {otp}")

class IndiaNotificationFactory(NotificationFactory):
    """For Indian users: Email + SMS + SMS-OTP"""
    def create_transactional(self):
        return EmailNotification("smtp.aws.amazon.com")

    def create_marketing(self):
        return SMSNotification("MSG91")   # Popular Indian SMS provider

    def create_otp(self):
        return SMSNotification("Exotel")  # Indian OTP provider

class USANotificationFactory(NotificationFactory):
    """For US users: Email + Push + Email-OTP"""
    def create_transactional(self):
        return EmailNotification("smtp.sendgrid.com")

    def create_marketing(self):
        return PushNotification("APNs")   # Apple Push Notification

    def create_otp(self):
        return EmailNotification("smtp.sendgrid.com")

class WhatsAppFirstFactory(NotificationFactory):
    """For markets where WhatsApp is primary"""
    def create_transactional(self):
        return WhatsAppNotification()

    def create_marketing(self):
        return WhatsAppNotification()

    def create_otp(self):
        return SMSNotification("Local")

# ─── Testing ───
print("=== Simple Factory ===")
channels = ["email", "sms", "push", "whatsapp"]
for ch in channels:
    notif  = create_notification(ch)
    result = notif.deliver(f"user@{ch}.com", "Your order #1234 is shipped!")
    print(f"  Result: {result}\n")

print("=== Abstract Factory: India vs USA ===")
def get_factory(country: str) -> NotificationFactory:
    """Factory of factories!"""
    factories = {
        "IN": IndiaNotificationFactory(),
        "US": USANotificationFactory(),
        "BR": WhatsAppFirstFactory(),
    }
    return factories.get(country, IndiaNotificationFactory())

for country in ["IN", "US", "BR"]:
    print(f"\n--- Country: {country} ---")
    factory = get_factory(country)
    factory.notify_user(
        f"user_{country}", "Payment received", "50% off today!", "482910"
    )
```

### 📖 Explanation:
```
PROBLEM:  You want to ADD BEHAVIOUR to objects dynamically at runtime
          WITHOUT modifying the original class
          WITHOUT creating a complex inheritance hierarchy

SOLUTION: Wrap the object in a Decorator that adds the new behaviour,
          while delegating the original behaviour to the wrapped object.

ANALOGY:  COFFEE SHOP ORDER
  Base coffee = ₹50
  Add milk    = Milk Decorator adds ₹20 → ₹70
  Add sugar   = Sugar Decorator adds ₹5 → ₹75
  Add caramel = Caramel Decorator adds ₹30 → ₹105

  EACH ADD-ON wraps the previous.
  The final price = all wrappers combined.
  You can mix ANY combination without pre-creating every combo class!

  Without Decorator: need classes for every combo:
  CoffeeWithMilk, CoffeeWithMilkAndSugar, CoffeeWithMilkSugarCaramel... (EXPLOSION!)

  With Decorator: Coffee → wrap(Milk) → wrap(Sugar) → wrap(Caramel)
```

```python name=decorator_pattern.py
# ══════════════════════════════════════════════════
#  PATTERN 3: DECORATOR PATTERN
#  Add behaviour dynamically without modifying class
# ══════════════════════════════════════════════════
from abc import ABC, abstractmethod

# ─── Component Interface ───
class DataProcessor(ABC):
    """Base interface — all processors and decorators implement this"""
    @abstractmethod
    def process(self, data: str) -> str: pass

    @abstractmethod
    def get_description(self) -> str: pass

    def __str__(self):
        return self.get_description()

# ─── Concrete Components (the base objects) ───
class RawDataProcessor(DataProcessor):
    """The simplest processor — just returns data as-is"""
    def process(self, data): return data
    def get_description(self): return "Raw Processor"

class FileDataProcessor(DataProcessor):
    """Reads data from a 'file' (simulated)"""
    def __init__(self, source="file.txt"):
        self.source = source

    def process(self, data):
        return f"[from:{self.source}] {data}"

    def get_description(self):
        return f"FileProcessor({self.source})"

# ─── Base Decorator ───
class DataProcessorDecorator(DataProcessor):
    """
    Base decorator class.
    Wraps another DataProcessor and delegates to it.
    All concrete decorators inherit from this.
    """
    def __init__(self, wrapped: DataProcessor):
        self._wrapped = wrapped   # HAS-A reference to what it wraps

    def process(self, data: str) -> str:
        return self._wrapped.process(data)   # delegate!

    def get_description(self) -> str:
        return self._wrapped.get_description()

# ─── Concrete Decorators — each adds ONE feature ───
class EncryptionDecorator(DataProcessorDecorator):
    """Adds encryption to whatever it wraps"""
    def __init__(self, wrapped, key="default_key"):
        super().__init__(wrapped)
        self.key = key

    def process(self, data: str) -> str:
        raw     = self._wrapped.process(data)   # get previous result
        # Simple Caesar cipher for demo
        encoded = ''.join(chr(ord(c)+3) for c in raw)
        return f"[ENCRYPTED:{self.key[:4]}] {encoded}"

    def get_description(self):
        return f"Encrypt({self._wrapped.get_description()})"

class CompressionDecorator(DataProcessorDecorator):
    """Adds compression"""
    def process(self, data: str) -> str:
        raw        = self._wrapped.process(data)
        compressed = raw.replace(' ', '_')[:50]  # simplified compression
        ratio      = len(compressed) / len(raw)
        return f"[COMPRESSED:{ratio:.0%}] {compressed}"

    def get_description(self):
        return f"Compress({self._wrapped.get_description()})"

class LoggingDecorator(DataProcessorDecorator):
    """Adds logging around processing"""
    def __init__(self, wrapped, logger_name="App"):
        super().__init__(wrapped)
        self.logger_name = logger_name

    def process(self, data: str) -> str:
        print(f"  📋 [{self.logger_name}] Processing {len(data)} chars...")
        result = self._wrapped.process(data)
        print(f"  📋 [{self.logger_name}] Done → {len(result)} chars output")
        return result

    def get_description(self):
        return f"Log({self._wrapped.get_description()})"

class ValidationDecorator(DataProcessorDecorator):
    """Validates data before processing"""
    def __init__(self, wrapped, max_length=1000):
        super().__init__(wrapped)
        self.max_length = max_length

    def process(self, data: str) -> str:
        if not data or not data.strip():
            raise ValueError("Empty data not allowed!")
        if len(data) > self.max_length:
            raise ValueError(f"Data too long: {len(data)} > {self.max_length}")
        print(f"  ✅ Validated: {len(data)} chars (max={self.max_length})")
        return self._wrapped.process(data)

    def get_description(self):
        return f"Validate({self._wrapped.get_description()})"

class CachingDecorator(DataProcessorDecorator):
    """Caches results for repeated inputs"""
    def __init__(self, wrapped):
        super().__init__(wrapped)
        self._cache = {}
        self._hits  = 0

    def process(self, data: str) -> str:
        if data in self._cache:
            self._hits += 1
            print(f"  ⚡ Cache hit! (total hits: {self._hits})")
            return self._cache[data]
        result             = self._wrapped.process(data)
        self._cache[data]  = result
        return result

    def get_description(self):
        return f"Cache({self._wrapped.get_description()})"

# ─── Testing: Build pipelines by stacking decorators ───
print("=== Decorator Pattern: Data Processing Pipeline ===\n")

base = RawDataProcessor()

# Pipeline 1: Validate → Log → Encrypt
pipeline1 = EncryptionDecorator(
    LoggingDecorator(
        ValidationDecorator(base),
        "Pipeline1"
    ),
    key="secret_key_123"
)
print(f"Pipeline 1: {pipeline1}")
result1 = pipeline1.process("Hello World — sensitive data!")
print(f"Result: {result1}\n")

# Pipeline 2: Cache → Validate → Compress → Log
pipeline2 = CachingDecorator(
    LoggingDecorator(
        CompressionDecorator(
            ValidationDecorator(base, max_length=500)
        ),
        "Pipeline2"
    )
)
print(f"Pipeline 2: {pipeline2}")
result2 = pipeline2.process("Repeated data to test cache")
print(f"Result: {result2[:60]}...")
print()
result2b = pipeline2.process("Repeated data to test cache")  # cache hit!
print(f"Result: {result2b[:60]}...\n")

# Pipeline 3: Add to file processor
file_pipeline = LoggingDecorator(
    EncryptionDecorator(
        FileDataProcessor("user_data.txt")
    ),
    "FileLogger"
)
print(f"Pipeline 3: {file_pipeline}")
file_pipeline.process("User personal information")

# ─── Real-World: HTTP Middleware Stack ───
print("\n=== Real-World: HTTP Request Decorator Stack ===\n")

class HTTPHandler(ABC):
    @abstractmethod
    def handle(self, request: dict) -> dict: pass

class BaseHandler(HTTPHandler):
    def handle(self, request):
        return {"status": 200, "body": f"Hello, {request.get('user', 'World')}!"}

class AuthMiddleware(HTTPHandler):
    def __init__(self, handler: HTTPHandler):
        self._handler = handler

    def handle(self, request):
        if not request.get('token'):
            return {"status": 401, "body": "Unauthorized"}
        print(f"  🔐 Auth: token verified")
        return self._handler.handle(request)

class RateLimitMiddleware(HTTPHandler):
    def __init__(self, handler: HTTPHandler, max_rps=100):
        self._handler = handler
        self.max_rps  = max_rps
        self._count   = 0

    def handle(self, request):
        self._count += 1
        if self._count > self.max_rps:
            return {"status": 429, "body": "Too Many Requests"}
        print(f"  ⏱️  Rate limit: {self._count}/{self.max_rps}")
        return self._handler.handle(request)

class LoggingMiddleware(HTTPHandler):
    def __init__(self, handler: HTTPHandler):
        self._handler = handler

    def handle(self, request):
        import datetime
        print(f"  📋 [{datetime.datetime.now().strftime('%H:%M:%S')}] "
              f"{request.get('method','GET')} {request.get('path','/')}")
        response = self._handler.handle(request)
        print(f"  📋 Response: {response['status']}")
        return response

# Build the middleware stack
app = LoggingMiddleware(
    RateLimitMiddleware(
        AuthMiddleware(
            BaseHandler()
        ),
        max_rps=5
    )
)

# Test requests
requests = [
    {"method": "GET",  "path": "/api/user",  "token": "abc123", "user": "Alice"},
    {"method": "POST", "path": "/api/order", "token": "xyz789", "user": "Bob"},
    {"method": "GET",  "path": "/api/data"},  # no token!
]
for req in requests:
    result = app.handle(req)
    print(f"  Final: {result}\n")
```
